windowclass.script:
-- The ordered list of convocation skills associated with Pvarism
local tConvocationSkills = { "FYVRIA", "JMORVI", "LYAHVI", "ODIVSHE", "PELEAHN", "SAVORYA", "NEUTRAL" };

-- Sort order keys: PVARISM sorts before its sub-skills, which sort before everything after P
local tConvSortOrder = {
	["FYVRIA"]  = "PVARISM_1",
	["JMORVI"]  = "PVARISM_2",
	["LYAHVI"]  = "PVARISM_3",
	["ODIVSHE"] = "PVARISM_4",
	["PELEAHN"] = "PVARISM_5",
	["SAVORYA"] = "PVARISM_6",
	["NEUTRAL"] = "PVARISM_7",
};

function getSortOrder(sName)
	local sUpper = string.upper(sName);
	if sUpper == "PVARISM" then
		return "PVARISM";  -- sorts before PVARISM_1, PVARISM_2 ...
	end
	local s = tConvSortOrder[sUpper];
	if s then return s; end
	return sUpper;  -- everything else sorts by its own uppercase name
end

function updateSortOrder()
	local sNameVal = name.getValue();
	local node = getDatabaseNode();
	if node and sNameVal ~= "" then
		DB.setValue(node, "sortorder", "string", getSortOrder(sNameVal));
	end
end

function isConvocationSkill(sName)
	local sUpper = string.upper(sName);
	for _, sCon in ipairs(tConvocationSkills) do
		if sUpper == sCon then return true; end
	end
	return false;
end

-- Sunsign modifier index per convocation (from HarnManager.getSunsignModifiers)
-- Returns {social[1], lore[2], physical[3], nature[4], craft[5], combat[6]}
local tConvModifierIndex = {
	["ODIVSHE"] = 1,  -- fatSocial
	["SAVORYA"] = 2,  -- fatLore
	["LYAHVI"]  = 3,  -- fatPhysical
	["FYVRIA"]  = 4,  -- fatNature
	["JMORVI"]  = 5,  -- fatCraft
	["PELEAHN"] = 6,  -- fatCombat
	["NEUTRAL"] = 0,  -- no sunsign modifier
};

-- Calculate ML for a convocation: PvarismML + sunsign modifier
function calculateConvocationML(nodeChar, sConvName)
	if not nodeChar then return 0; end
	-- Find Pvarism ML in the esotericalist
	local nPvarismML = 0;
	local nodeEsoList = DB.getChild(nodeChar, "esotericalist");
	if nodeEsoList then
		for _, nodeSkill in pairs(DB.getChildren(nodeEsoList)) do
			if string.upper(DB.getValue(nodeSkill, "name", "")) == "PVARISM" then
				nPvarismML = DB.getValue(nodeSkill, "ml", 0);
				break;
			end
		end
	end
	-- Get sunsign modifier for this convocation
	local nModIdx = tConvModifierIndex[string.upper(sConvName)] or 0;
	local nMod = 0;
	if nModIdx > 0 and HarnManager and HarnManager.getSunsignModifiers then
		local sSunsign = DB.getValue(nodeChar, "birth_sunsign", "");
		local tMods = HarnManager.getSunsignModifiers(sSunsign);
		nMod = tMods[nModIdx] or 0;
	end
	return nPvarismML + nMod;
end

function updateVisibility()
	local sNameVal = name.getValue();
	if isConvocationSkill(sNameVal) then
		local sUpper = string.upper(sNameVal);
		if sNameVal ~= sUpper then
			name.setValue(sUpper);
		end
		name.setFont("harn_skill_12");
		-- Hide SM and SB for convocations - they don't use them
		sm.setVisible(false);
		sb.setVisible(false);
		att1.setVisible(false);
		att2.setVisible(false);
	else
		name.setFont("sheettext");
		sm.setVisible(true);
		sb.setVisible(true);
		att1.setVisible(true);
		att2.setVisible(true);
	end
end

function onInit()
	local node = getDatabaseNode();
	if node then
		DB.addHandler(node.getPath() .. ".name", "onUpdate", onNameUpdate);
	end
	updateVisibility();
	updateSortOrder();
end

function onClose()
	local node = getDatabaseNode();
	if node then
		DB.removeHandler(node.getPath() .. ".name", "onUpdate", onNameUpdate);
	end
end

function onNameUpdate()
	updateVisibility();
	updateSortOrder();
end

function setCustomEditMode(bEdit)
	btn_recalc.setVisible(bEdit);
	if bEdit then
		local sNameVal = name.getValue();
		-- Convocation sub-skills cannot be independently deleted
		if isConvocationSkill(sNameVal) then
			btn_delete.setVisible(false);
			return;
		end
		local bDeletable = false;
		if SkillsData then
			local rSkill = SkillsData.getSkill(sNameVal);
			if rSkill then
				if rSkill.sm == 0 and sNameVal ~= "Spirit" then
					bDeletable = true;
				end
			else
				bDeletable = true;
			end
		else
			bDeletable = true;
		end
		btn_delete.setVisible(bDeletable);
	else
		btn_delete.setVisible(false);
	end
end

stringfield.script:
function onLoseFocus()
	local sName = getValue();
	if sName == "" then return; end

	Debug.console("Esoterica skill name entered: " .. sName);

	-- If Pvarism was entered, auto-add the 7 convocation skills
	if string.upper(sName) == "PVARISM" then
		local nodeCharSkill = window.getDatabaseNode();
		if nodeCharSkill then
			-- Set PVARISM's own sortorder
			DB.setValue(nodeCharSkill, "sortorder", "string", "PVARISM");
			local nodeList = nodeCharSkill.getParent();
			if nodeList then
				local tConvSkills = {
					{ name="FYVRIA",  sort="PVARISM_1" },
					{ name="JMORVI",  sort="PVARISM_2" },
					{ name="LYAHVI",  sort="PVARISM_3" },
					{ name="ODIVSHE", sort="PVARISM_4" },
					{ name="PELEAHN", sort="PVARISM_5" },
					{ name="SAVORYA", sort="PVARISM_6" },
					{ name="NEUTRAL", sort="PVARISM_7" },
				};
				for _, tEntry in ipairs(tConvSkills) do
					-- Check if it already exists
					local bExists = false;
					for _, nodeExisting in pairs(DB.getChildren(nodeList)) do
						if string.upper(DB.getValue(nodeExisting, "name", "")) == tEntry.name then
							bExists = true;
							break;
						end
					end
					if not bExists then
						local nodeNew = DB.createChild(nodeList);
						DB.setValue(nodeNew, "name", "string", tEntry.name);
						DB.setValue(nodeNew, "sortorder", "string", tEntry.sort);
						Debug.console("Added convocation skill: " .. tEntry.name);
					end
				end
			end
		end
		-- fall through to look up Pvarism's own att1/att2/sm from the skills db
	end

	-- Look up skill data from database (Esoterica group only)
	local nodeSkillsRef = DB.findNode("harnmaster.skills");
	if nodeSkillsRef then
		for _, nodeRefSkill in pairs(DB.getChildren(nodeSkillsRef)) do
			local sGroup = DB.getValue(nodeRefSkill, "group", "");
			if sGroup == "Esoterica" and DB.getValue(nodeRefSkill, "name", "") == sName then
				local sAtt1 = DB.getValue(nodeRefSkill, "att1", "");
				local sAtt2 = DB.getValue(nodeRefSkill, "att2", "");
				local nSM = DB.getValue(nodeRefSkill, "sm", 0);

				Debug.console("Found esoterica skill: att1=" .. sAtt1 .. ", att2=" .. sAtt2 .. ", sm=" .. tostring(nSM));

				-- Update fields in character's skill entry
				local nodeCharSkill = window.getDatabaseNode();
				if nodeCharSkill then
					DB.setValue(nodeCharSkill, "att1", "string", sAtt1);
					DB.setValue(nodeCharSkill, "att2", "string", sAtt2);
					DB.setValue(nodeCharSkill, "sm", "number", nSM);

					-- Calculate SB from character attributes
					local nodeChar = nodeCharSkill.getParent().getParent();
					if nodeChar then
						local sAtt1Field = string.lower(sAtt1) .. "_score";
						local sAtt2Field = string.lower(sAtt2) .. "_score";
						local nAtt1Value = DB.getValue(nodeChar, sAtt1Field, 0);
						local nAtt2Value = DB.getValue(nodeChar, sAtt2Field, 0);

						local nSB = 0;
						if nAtt1Value > 0 or nAtt2Value > 0 then
							local nAvg = (nAtt1Value + nAtt2Value) / 2;
							if nAtt1Value > nAtt2Value then
								nSB = math.ceil(nAvg);
							else
								nSB = math.floor(nAvg);
							end
						end
						DB.setValue(nodeCharSkill, "sb", "number", nSB);
					end
				end
				return;
			end
		end
		Debug.console("Esoterica skill not found: " .. sName);
	end
end

buttoncontrol.script:
function onButtonPress()
	local nodeBase = window.getDatabaseNode();
	if nodeBase then
		local sNameVal = DB.getValue(nodeBase, "name", "");
		if window.isConvocationSkill(sNameVal) then
			-- Use convocation ML formula: PvarismML + sunsign modifier
			local nodeChar = nodeBase.getParent().getParent();
			local nML = window.calculateConvocationML(nodeChar, sNameVal);
			DB.setValue(nodeBase, "ml", "number", nML);
		else
			-- Standard recalc: SM * SB
			local nSM = DB.getValue(nodeBase, "sm", 0);
			local nSB = DB.getValue(nodeBase, "sb", 0);
			DB.setValue(nodeBase, "ml", "number", nSM * nSB);
		end
	end
end

function onButtonPress()
	local nodeBase = window.getDatabaseNode();
	if nodeBase then
		local sNameVal = DB.getValue(nodeBase, "name", "");
		-- If deleting Pvarism, also remove the 7 convocation skills
		if string.upper(sNameVal) == "PVARISM" then
			local tConvSkills = { "FYVRIA", "JMORVI", "LYAHVI", "ODIVSHE", "PELEAHN", "SAVORYA", "NEUTRAL" };
			local nodeList = nodeBase.getParent();
			if nodeList then
				local tToDelete = {};
				for _, nodeChild in pairs(DB.getChildren(nodeList)) do
					local sChildName = string.upper(DB.getValue(nodeChild, "name", ""));
					for _, sCon in ipairs(tConvSkills) do
						if sChildName == sCon then
							table.insert(tToDelete, nodeChild);
							break;
						end
					end
				end
				for _, nodeChild in ipairs(tToDelete) do
					nodeChild.delete();
				end
			end
		end
		nodeBase.delete();
	end
end

stringfield.script:
function onLoseFocus()
	local sName = getValue();
	if sName == "" then return; end

	Debug.console("Spell name entered: " .. sName);

	-- Look up spell data from database
	local nodeSpellsRef = DB.findNode("harnmaster.spells");
	if nodeSpellsRef then
		for _, nodeRefSpell in pairs(DB.getChildren(nodeSpellsRef)) do
			if DB.getValue(nodeRefSpell, "name", "") == sName then
				local sConv = DB.getValue(nodeRefSpell, "conv", "");
				local nCmp = DB.getValue(nodeRefSpell, "cmp", 0);

				Debug.console("Found spell: conv=" .. sConv .. ", cmp=" .. tostring(nCmp));

				-- Update fields in character's spell entry
				local nodeCharSpell = window.getDatabaseNode();
				if nodeCharSpell then
					DB.setValue(nodeCharSpell, "conv", "string", sConv);
					DB.setValue(nodeCharSpell, "cmp", "number", nCmp);
				end
				return;
			end
		end
		Debug.console("Spell not found: " .. sName);
	end
end

